structure.mermaidSource:
flowchart TD
  start["Início: Conjunção 'E' Identificada"] --> proc_isolar["Isolar orações/termos conectados e analisar contexto semântico"]
  proc_isolar --> dec_oposi{"Há contraste ou quebra de expectativa?<br/>(comutável por 'mas' ou 'porém')"}
  dec_oposi -- "Sim" --> res_adversativo["Valor ADVERSATIVO<br/>Equivale a 'mas' / 'porém'<br/>Ex: Estudou muito, e reprovou"]
  dec_oposi -- "Não" --> dec_conclusao{"Introduz consequência ou conclusão lógica?<br/>(comutável por 'portanto' ou 'por isso')"}
  dec_conclusao -- "Sim" --> res_conclusivo["Valor CONCLUSIVO<br/>Equivale a 'logo' / 'portanto'<br/>Ex: Fez sol, e fomos à praia"]
  dec_conclusao -- "Não" --> dec_temporal{"Expressa sucessão cronológica imediata?<br/>(comutável por 'e em seguida')"}
  dec_temporal -- "Sim" --> res_temporal["Valor TEMPORAL<br/>Sucessão narrativa de ações<br/>Ex: Abriu a porta e saiu correndo"]
  dec_temporal -- "Não" --> res_aditivo["Valor ADITIVO TÍPICO<br/>Soma pura de elementos coordenados<br/>Ex: Trabalha e estuda todos os dias"]

flowchart TD
  start["Início: Proposta de inserção de ';' no período"] --> dec_coord{"As orações são coordenadas?"}
  dec_coord -- "Não (são subordinadas)" --> res_err_sintaxe["Item ERRADO:\nInadequação sintática do ponto e vírgula"]
  dec_coord -- "Sim (são coordenadas)" --> proc_termo["Inspecionar termo imediatamente após o ';'"]
  proc_termo --> dec_pronome{"Termo é pronome oblíquo átono?"}
  dec_pronome -- "Não (outro vocábulo)" --> res_ok_termo["Item CERTO:\nSubstituição válida sem vício pronominal"]
  dec_pronome -- "Sim (me, te, se...)" --> dec_enclise{"Houve ajuste do verbo para ênclise?"}
  dec_enclise -- "Não (manteve próclise: '; te deixa')" --> res_err_proclise["Item ERRADO:\nViolação de colocação pronominal"]
  dec_enclise -- "Sim (ajustou para ênclise: '; deixa-te')" --> res_ok_enclise["Item CERTO:\nPontuação e ênclise regulares"]

flowchart TD
  start["Início: Mantra da Causa"] --> proc_formula["Montar Fórmula Causal:<br/>'O fato de [Oração Conectivo] fez com que [Oração Principal]?'"]
  proc_formula --> dec_imperativo{"Oração principal é comando imperativo, convite ou conselho?"}
  dec_imperativo -- "Sim" --> res_explicativa_cmd["Oração Coordenada Explicativa<br/>(Comando/convite/conselho)"]
  dec_imperativo -- "Não" --> dec_indicativo{"Oração principal relata fato consumado no indicativo?"}
  dec_indicativo -- "Não" --> res_explicativa_logica["Oração Coordenada Explicativa<br/>(Dedução lógica/justificativa)"]
  dec_indicativo -- "Sim" --> dec_fato_gerador{"A fórmula faz sentido fático?<br/>(Oração conectiva causou o fato da principal?)"}
  dec_fato_gerador -- "Sim" --> res_causal["Oração Subordinada Adverbial Causal<br/>(Fato gerador prévio consumado)"]
  dec_fato_gerador -- "Não" --> res_explicativa_logica
